import sys


def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    old_limit = sys.getrecursionlimit()
    if old_limit < 20000:
        sys.setrecursionlimit(20000)

    def tokenize(expr: str) -> list[tuple[str, str]]:
        tokens: list[tuple[str, str]] = []
        i = 0
        n = len(expr)
        while i < n:
            ch = expr[i]
            if ch.isspace():
                i += 1
            elif ch.isdigit():
                j = i
                while j < n and expr[j].isdigit():
                    j += 1
                tokens.append(("NUM", expr[i:j]))
                i = j
            elif ch.isalpha():
                j = i
                while j < n and expr[j].isalnum():
                    j += 1
                tokens.append(("ID", expr[i:j]))
                i = j
            elif i + 1 < n and expr[i : i + 2] in ("<=", ">=", "<>"):
                tokens.append(("OP", expr[i : i + 2]))
                i += 2
            elif ch in "+-*/(),:<=>":
                tokens.append((ch, ch))
                i += 1
            else:
                raise ValueError(f"Unexpected character: {ch!r}")
        return tokens

    class Parser:
        def __init__(self, tokens: list[tuple[str, str]]) -> None:
            self.tokens = tokens
            self.pos = 0

        def peek(self, offset: int = 0) -> tuple[str, str] | None:
            idx = self.pos + offset
            if idx < len(self.tokens):
                return self.tokens[idx]
            return None

        def consume(self, expected: str | None = None) -> tuple[str, str]:
            tok = self.tokens[self.pos]
            if expected is not None and tok[0] != expected:
                raise ValueError(f"Expected {expected}, got {tok}")
            self.pos += 1
            return tok

        def parse_formula(self):
            node = self.parse_term()
            while (tok := self.peek()) is not None and tok[0] in ("+", "-"):
                op = self.consume()[0]
                right = self.parse_term()
                node = ("BIN", op, node, right)
            return node

        def parse_term(self):
            node = self.parse_unary()
            while (tok := self.peek()) is not None and tok[0] in ("*", "/"):
                op = self.consume()[0]
                right = self.parse_unary()
                node = ("BIN", op, node, right)
            return node

        def parse_unary(self):
            if (tok := self.peek()) is not None and tok[0] == "-":
                self.consume()
                return ("NEG", self.parse_unary())
            return self.parse_atom()

        def parse_atom(self):
            tok = self.peek()
            assert tok is not None
            kind, val = tok
            if kind == "NUM":
                self.consume()
                return ("NUM", int(val))
            if kind == "(":
                self.consume()
                node = self.parse_formula()
                self.consume(")")
                return node
            if kind == "ID":
                nxt = self.peek(1)
                if nxt is not None and nxt[0] == "(":
                    return self.parse_call()
                self.consume()
                return ("CELL", val)
            raise ValueError(f"Unexpected token: {tok}")

        def parse_call(self):
            name = self.consume("ID")[1]
            self.consume("(")
            if name == "IF":
                left = self.parse_formula()
                op_tok = self.consume()
                op = op_tok[1]
                right = self.parse_formula()
                self.consume(",")
                then_expr = self.parse_formula()
                self.consume(",")
                else_expr = self.parse_formula()
                self.consume(")")
                return ("IF", op, left, right, then_expr, else_expr)
            args = []
            while True:
                t0 = self.peek(0)
                t1 = self.peek(1)
                if (
                    t0 is not None
                    and t0[0] == "ID"
                    and t1 is not None
                    and t1[0] == ":"
                ):
                    c1 = self.consume("ID")[1]
                    self.consume(":")
                    c2 = self.consume("ID")[1]
                    args.append(("RANGE", c1, c2))
                else:
                    args.append(("EXPR", self.parse_formula()))
                if (nxt := self.peek()) is not None and nxt[0] == ",":
                    self.consume(",")
                else:
                    break
            self.consume(")")
            return ("FUNC", name, args)

    memo: dict[str, int | str] = {}
    visiting: set[str] = set()

    def eval_cell(name: str) -> int | str:
        if name not in cells:
            return 0
        if name in memo:
            return memo[name]
        if name in visiting:
            return "#CYCLE!"
        visiting.add(name)
        raw = cells[name]
        if raw.startswith("="):
            ast = Parser(tokenize(raw[1:])).parse_formula()
            res = eval_ast(ast)
        else:
            res = int(raw)
        visiting.remove(name)
        memo[name] = res
        return res

    def eval_ast(node) -> int | str:
        kind = node[0]
        if kind == "NUM":
            return node[1]
        if kind == "CELL":
            return eval_cell(node[1])
        if kind == "NEG":
            v = eval_ast(node[1])
            return v if isinstance(v, str) else -v
        if kind == "BIN":
            _, op, left, right = node
            lv = eval_ast(left)
            if isinstance(lv, str):
                return lv
            rv = eval_ast(right)
            if isinstance(rv, str):
                return rv
            if op == "+":
                return lv + rv
            if op == "-":
                return lv - rv
            if op == "*":
                return lv * rv
            if rv == 0:
                return "#DIV/0!"
            q = abs(lv) // abs(rv)
            return -q if (lv < 0) ^ (rv < 0) else q
        if kind == "IF":
            _, op, left, right, then_expr, else_expr = node
            lv = eval_ast(left)
            if isinstance(lv, str):
                return lv
            rv = eval_ast(right)
            if isinstance(rv, str):
                return rv
            if op == "=":
                cond = lv == rv
            elif op == "<>":
                cond = lv != rv
            elif op == "<":
                cond = lv < rv
            elif op == "<=":
                cond = lv <= rv
            elif op == ">":
                cond = lv > rv
            else:
                cond = lv >= rv
            return eval_ast(then_expr if cond else else_expr)
        if kind == "FUNC":
            _, name, args = node
            vals: list[int] = []
            for arg in args:
                if arg[0] == "EXPR":
                    v = eval_ast(arg[1])
                    if isinstance(v, str):
                        return v
                    vals.append(v)
                else:
                    _, c1, c2 = arg
                    col1, row1 = ord(c1[0]), int(c1[1:])
                    col2, row2 = ord(c2[0]), int(c2[1:])
                    r_lo, r_hi = min(row1, row2), max(row1, row2)
                    c_lo, c_hi = min(col1, col2), max(col1, col2)
                    for r in range(r_lo, r_hi + 1):
                        for c in range(c_lo, c_hi + 1):
                            cname = f"{chr(c)}{r}"
                            if cname in cells:
                                v = eval_cell(cname)
                                if isinstance(v, str):
                                    return v
                                vals.append(v)
            if not vals:
                return 0
            if name == "SUM":
                return sum(vals)
            if name == "MIN":
                return min(vals)
            return max(vals)
        raise ValueError(f"Unknown AST node: {node}")

    return {name: eval_cell(name) for name in cells}
